// ---- Scripture card runtime (outside the animation region) ----
// The heading word is a set-once hidden field (f0); paint it into the visible heading.
function paintHeading() {
  var src = document.getElementById('f0');
  var shown = document.querySelector('.scripture-label');
  if (src && shown) shown.textContent = src.textContent || '';
  var mask = shown ? shown.parentNode : null;
  if (mask && mask.classList) mask.classList.toggle('scripture-empty', !/\\S/.test(shown.textContent || ''));
}

// Fit ladder: the panel grows upward with the reading; when a long reading would push the
// panel above the middle of the frame, step the readings' type down (never below 0.72, which
// is still ~30px). If the lowest rung still does not fit, report it to the operator panel.
var scriptureOverflow = [];
var SCRIPTURE_MAX_BOX = 500;   /* px at --scale 1: the panel's top stays near mid-frame */
function fitPlacedText() {
  var root = document.documentElement;
  var box = document.querySelector('.scripture-box');
  if (!box || !root) return;
  var scale = parseFloat(getComputedStyle(root).getPropertyValue('--scale')) || 1;
  var limit = SCRIPTURE_MAX_BOX * scale;
  var rungs = [1, 0.94, 0.88, 0.83, 0.78, 0.74, 0.72];
  var i;
  for (i = 0; i < rungs.length; i++) {
    root.style.setProperty('--verse-fit', String(rungs[i]));
    if (box.offsetHeight <= limit) break;
  }
  scriptureOverflow = (i >= rungs.length) ? ['f1', 'f2'] : [];
}
function noacgTextOverflow() { return scriptureOverflow.slice(); }

(function () {
  var baseUpdate = update;
  update = function (data) {
    var out = baseUpdate(data);
    paintHeading();
    fitPlacedText();
    return out;
  };
  function ready() {
    paintHeading();
    fitPlacedText();
    if (document.fonts && document.fonts.ready) document.fonts.ready.then(function () { fitPlacedText(); });
  }
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', ready);
  else ready();
})();
'''
s=s.rstrip('\n')+'\n'+extra
